const MODES={
0:{title:['Footpath Stall','ফুটপাতের দোকান'],kind:'goods',image:'assets/icon/roadside_stall.png',products:[{id:'chips',name:['Chips','চিপস'],price:20,cost:10,stock:12},{id:'biscuit',name:['Biscuits','বিস্কুট'],price:10,cost:5,stock:18},{id:'water',name:['Bottled water','পানির বোতল'],price:20,cost:10,stock:10},{id:'soda',name:['Soft drink','সফট ড্রিংক'],price:30,cost:15,stock:8},{id:'candy',name:['Candy','ক্যান্ডি'],price:5,cost:2,stock:20}]},
1:{title:['Tea Stall','চায়ের দোকান'],kind:'tea',image:'assets/icon/tea_stall.png',products:[{id:'milk-tea',name:['Milk tea','দুধ চা'],price:20,cost:8,stock:20},{id:'red-tea',name:['Red tea','লাল চা'],price:10,cost:4,stock:20},{id:'biscuit',name:['Biscuits','বিস্কুট'],price:10,cost:5,stock:16},{id:'toast',name:['Toast','টোস্ট'],price:15,cost:7,stock:12}]},
2:{title:['Fuchka Wala','ফুচকাওয়ালা'],kind:'fuchka',image:'assets/icon/fuchka.png',products:[{id:'fuchka',name:['Fuchka serving','ফুচকার প্লেট'],price:50,cost:20,stock:20},{id:'extra-spicy',name:['Extra-spicy serving','ঝাল ফুচকা'],price:60,cost:25,stock:12},{id:'dahi',name:['Dahi fuchka','দই ফুচকা'],price:70,cost:30,stock:10}]}}
const txt=(p,l)=>p[l==='bn'?1:0];
function stallMarkup(kind,title,language){
 const label=txt(title,language);
 if(kind==='tea') return `<div class="sg-built-stall sg-built-tea" role="img" aria-label="${label}"><div class="sg-stall-roof"><i></i><i></i><i></i><i></i></div><div class="sg-stall-sign">চায়ের দোকান <small>CHA · BISCUIT</small></div><div class="sg-stall-frame"><div class="sg-stall-shelf"><b>▰</b><b>▰</b><b>▰</b></div><div class="sg-stall-counter"><span class="sg-kettle"></span><span class="sg-cups"><i></i><i></i><i></i></span></div></div><div class="sg-stall-legs"><i></i><i></i></div></div>`;
 if(kind==='fuchka') return `<div class="sg-built-stall sg-built-fuchka" role="img" aria-label="${label}"><div class="sg-cart-umbrella"><i></i><i></i><i></i><i></i></div><div class="sg-cart-sign">ফুচকা <small>FUCHKA WALA</small></div><div class="sg-cart-body"><div class="sg-cart-bowls"><i></i><i></i><i></i></div><div class="sg-cart-front">ঢাকা স্ট্রিট ফুড</div></div><div class="sg-cart-wheel left"></div><div class="sg-cart-wheel right"></div></div>`;
 return `<div class="sg-built-stall sg-built-goods" role="img" aria-label="${label}"><div class="sg-goods-awning"><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="sg-goods-sign">দৈনন্দিন পণ্য <small>SNACKS · DRINKS</small></div><div class="sg-goods-shelves"><div><i></i><i></i><i></i><i></i></div><div><i></i><i></i><i></i><i></i></div><div><i></i><i></i><i></i><i></i></div></div><div class="sg-goods-counter"></div><div class="sg-goods-post left"></div><div class="sg-goods-post right"></div></div>`;
}
export function startStallGame(variant=0,{language='en',onExit=()=>{}}={}){
 const mode=MODES[Number(variant)]||MODES[0],tr=(a,b)=>language==='bn'?b:a;let stock=mode.products.map(p=>({...p})),cash=200,served=0,customerNo=0,queue=[],selected=new Map(),prepared=false,finished=false,feedback='',arrivalTimer;
 const root=document.createElement('section');root.className='standalone-stall';root.setAttribute('aria-label',txt(mode.title,language));const oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';document.body.append(root);
 const sum=c=>c.price*c.qty;
 function arrive(){if(finished||queue.length>=2||!stock.some(p=>p.stock>0))return;customerNo++;const p=stock.filter(x=>x.stock>0)[Math.floor(Math.random()*stock.filter(x=>x.stock>0).length)];queue.push({id:customerNo,productId:p.id,qty:1+Math.floor(Math.random()*Math.min(2,p.stock)),price:p.price,name:p.name,avatar:['🧔🏽','👩🏽','👨🏽','👩🏻','🧑🏽'][Math.floor(Math.random()*5)],arriving:true});selected.clear();prepared=false;feedback=tr(`Customer #${customerNo} has arrived.`,`ক্রেতা #${customerNo} এসে গেছে।`);render();setTimeout(()=>{const c=queue.find(x=>x.id===customerNo);if(c)c.arriving=false;render()},650);schedule();}
 function schedule(){clearTimeout(arrivalTimer);if(!finished&&queue.length<2&&stock.some(p=>p.stock>0))arrivalTimer=setTimeout(arrive,2400+Math.random()*1800)}
 function render(){const c=queue[0];root.innerHTML=`<div class="sg-shell"><header class="sg-top"><div><span class="sg-kicker">DHAKA TERROR · POV BANGLADESH</span><h1>${txt(mode.title,language)}</h1><p>${tr('Run your stall and serve up to two customers at once.','দোকান চালান, একসঙ্গে সর্বোচ্চ দুই ক্রেতাকে সেবা দিন।')}</p></div><div class="sg-actions"><button data-a="lang">${language==='en'?'বাংলা':'English'}</button><button data-a="exit">← ${tr('Main menu','মূল মেনু')}</button></div></header><div class="sg-layout"><section class="sg-scene sg-${mode.kind}"><div class="sg-scene-heading"><span>${tr('ROAD-SIDE BUSINESS','রাস্তার পাশের দোকান')}</span><b>${queue.length}/2 ${tr('CUSTOMERS','ক্রেতা')}</b></div><div class="sg-backdrop">${stallMarkup(mode.kind,mode.title,language)}<div class="sg-counter"><b>${txt(mode.title,language)}</b></div></div><div class="sg-customer-area"><label>${tr('CUSTOMERS AT YOUR STALL','দোকানে আসা ক্রেতা')}</label><div class="sg-customer-row">${[0,1].map(i=>{let x=queue[i];return x?`<div class="sg-customer ${x.arriving?'is-arriving':''} ${i===0?'is-serving':'is-waiting'}"><span class="sg-avatar">${x.avatar}</span><span><b>${tr('Customer','ক্রেতা')} #${x.id}</b><small>${i===0?tr('Ordering now','অর্ডার দিচ্ছে'):tr('Waiting next','অপেক্ষায়')}</small></span>${i===0?'<i class="sg-order-dot"></i>':''}</div>`:`<div class="sg-customer sg-empty"><span>＋</span><small>${tr('Space available','জায়গা খালি')}</small></div>`}).join('')}</div><div class="sg-exit-lane">🚶🏽 <span>${tr('Arrive  →  order  →  leave','আসে → অর্ডার দেয় → চলে যায়')}</span> 🚶🏻‍♀️</div></div><p class="sg-scene-caption">${tr('A little roadside business in Bangladesh','বাংলাদেশের ছোট্ট রাস্তার পাশের দোকান')}</p></section><section class="sg-panel"><div class="sg-stats"><div><small>${tr('CASH','নগদ')}</small><strong>৳${cash}</strong></div><div><small>${tr('SERVED','সেবা')}</small><strong>${served}</strong></div><div><small>${tr('SHIFT','শিফট')}</small><strong>${finished?tr('DONE','শেষ'):`${Math.min(served,10)}/10`}</strong></div></div><div class="sg-order"><small>${tr('CUSTOMER ORDER','ক্রেতার অর্ডার')} ${c?'#'+c.id:''}</small><h2>${c?`${txt(c.name,language)} × ${c.qty}`:tr('Waiting for a customer…','ক্রেতার অপেক্ষায়…')}</h2>${c?`<p>${tr('Order total','মোট দাম')}: <b>৳${sum(c)}</b></p>`:''}<div class="sg-products">${stock.map(p=>`<div class="sg-row"><span>${txt(p.name,language)} <small>৳${p.price} · ${tr('stock','স্টক')} ${p.stock}</small></span><div><button data-q="${p.id}" data-d="-1" ${!selected.get(p.id)?'disabled':''}>−</button><b>${selected.get(p.id)||0}</b><button data-q="${p.id}" data-d="1" ${!c||p.stock<1?'disabled':''}>+</button></div></div>`).join('')}</div><div class="sg-buttons">${mode.kind==='tea'?`<button class="sg-secondary" data-a="prepare" ${!c?'disabled':''}>${prepared?tr('Tea prepared ✓','চা তৈরি ✓'):tr('Prepare tea','চা তৈরি করুন')}</button>`:''}<button class="sg-primary" data-a="serve" ${!c||finished?'disabled':''}>${tr('Serve & send customer','পরিবেশন করে বিদায় দিন')} →</button><button class="sg-secondary" data-a="next" ${finished||queue.length>=2?'disabled':''}>＋ ${tr('Welcome next customer','পরের ক্রেতাকে স্বাগত')}</button></div><p class="sg-feedback" role="status">${feedback||tr('Select the exact requested item and quantity.','সঠিক পণ্য ও পরিমাণ বেছে নিন।')}</p></div><div class="sg-restock"><h3>${tr('Restock','স্টক কিনুন')}</h3>${stock.map(p=>`<button data-r="${p.id}" ${cash<p.cost||p.stock>=30?'disabled':''}>+ ${txt(p.name,language)} · ৳${p.cost}</button>`).join('')}</div><button class="sg-secondary sg-end" data-a="finish">${tr('Finish shift','শিফট শেষ করুন')}</button></section></div></div>`;
 root.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>{let a=b.dataset.a;if(a==='exit'){cleanup();onExit()}else if(a==='lang'){language=language==='en'?'bn':'en';render()}else if(a==='next'){if(queue.length<2)arrive();else{feedback=tr('Both customer spots are occupied.','দুইটি ক্রেতার জায়গাই পূর্ণ।');render()}}else if(a==='prepare'){prepared=true;feedback=tr('Tea is ready to serve.','চা পরিবেশনের জন্য তৈরি।');render()}else if(a==='serve')serve();else if(a==='finish'){finished=true;clearTimeout(arrivalTimer);queue=[];feedback=tr('Shift complete. Return to the menu.','শিফট শেষ। মেনুতে ফিরুন।');render()}});
 root.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{let p=stock.find(x=>x.id===b.dataset.q),n=(selected.get(p.id)||0)+Number(b.dataset.d);if(n<0||n>p.stock)return;if(n)selected.set(p.id,n);else selected.delete(p.id);render()});root.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{let p=stock.find(x=>x.id===b.dataset.r);if(!p||cash<p.cost||p.stock>=30)return;cash-=p.cost;p.stock++;feedback=tr('One unit restocked.','একটি পণ্য স্টকে যোগ হয়েছে।');render()});
 }
 function serve(){let c=queue[0];if(!c||finished)return;let p=stock.find(x=>x.id===c.productId),n=[...selected.values()].reduce((a,b)=>a+b,0);if(mode.kind==='tea'&&c.productId.includes('tea')&&!prepared){feedback=tr('Prepare the tea before serving.','পরিবেশনের আগে চা তৈরি করুন।');render();return}if(selected.size!==1||selected.get(c.productId)!==c.qty||n!==c.qty){feedback=tr('Order mismatch — select the requested item and quantity.','অর্ডার মেলেনি—সঠিক পণ্য ও পরিমাণ বেছে নিন।');render();return}if(!p||p.stock<c.qty){feedback=tr('Not enough stock. Restock first.','পর্যাপ্ত স্টক নেই। আগে পণ্য তুলুন।');render();return}p.stock-=c.qty;cash+=sum(c);served++;queue.shift();selected.clear();prepared=false;feedback=tr(`Customer #${c.id} served and leaving now!`,`ক্রেতা #${c.id} সেবা নিয়ে চলে যাচ্ছে!`);render();const toast=document.createElement('div');toast.className='sg-departure-toast';toast.textContent=`${c.avatar} ${tr('Customer','ক্রেতা')} #${c.id} ${tr('leaves happy ✓','খুশি মনে চলে গেল ✓')}`;root.append(toast);setTimeout(()=>toast.remove(),1500);if(served>=10){finished=true;queue=[];clearTimeout(arrivalTimer);feedback=tr('Shift complete!','শিফট শেষ!');render()}else schedule()}
 function cleanup(){clearTimeout(arrivalTimer);root.remove();document.body.style.overflow=oldOverflow}arrive();return{close:cleanup}
}
